type Role = 'admin' | 'supervisor' | 'operator';
type IncidentStatus = 'Draft' | 'Open' | 'Monitoring' | 'Resolved' | 'Closed' | 'Cancel';
type IncidentCondition = 'DOWN' | 'UP - Degraded';

interface ProfileRecord { userId: string; workspaceId: string; role: Role; email: string; name: string; createdAt: number; }
interface MemberRecord extends ProfileRecord { joinedAt: number; }
interface AttachmentRecord { id: string; path: string; name: string; type: string; size: number; uploadedAt: number; uploadedBy: string; }
interface GeoCoordinateRecord { id: string; latitude: number; longitude: number; normalized: string; sourceName: string; rawCoordinate: string; extractedAt: number; extractedBy: string; confidence?: 'high' | 'medium'; verified?: boolean; verifiedAt?: number; verifiedBy?: string; }
interface CutPointRecord { id: string; label: string; coordinate: GeoCoordinateRecord | null; }
interface IncidentRecord {
  identityMode: 'standard' | 'b2b'; b2bTitle: string; group: string; status: IncidentStatus; severity: 'Critical' | 'Major' | 'Minor'; condition: IncidentCondition; linkA: string; linkB: string; routeSegment: string; systemKey: string; parentIncidentId: string; incidentId: string; titleOverride: string; mduTicket: string; occurTime: string; dispatchTime: string; closedTime: string; picArea: string; picName: string; rootCause: string; cutPoint: string; action: string; reporter: string; internalNotes: string; impacts: Array<Record<string, unknown>>; progress: Array<Record<string, unknown>>; attachments: AttachmentRecord[]; cutPoints: CutPointRecord[]; geoCoordinates: GeoCoordinateRecord[]; checklist: Record<string, boolean>; closingEvidenceNote: string; assignedToUserId: string; assignedToName: string; acknowledgedAt: number; acknowledgedBy: string; handoverNote: string; handoverAt: number; handoverBy: string; reopenReason: string; resolvedAt: number; resolvedBy: string; deletedAt: number; deletedBy: string; deleteReason: string; createdAt: number; createdBy: string; updatedAt: number; updatedBy: string; revision: number;
}
interface SettingsRecord { groups: string[]; picAreas: string[]; picNames: string[]; rootCauses: string[]; actions: string[]; progressPhrases: string[]; sites: string[]; slaCriticalMinutes: number; slaMajorMinutes: number; slaMinorMinutes: number; staleUpdateMinutes: number; updatedAt: number; }
interface AuditRecord { action: string; summary: string; changedFields: string[]; fromRevision: number; toRevision: number; actorId: string; actorName: string; createdAt: number; }
interface SlaWorkspaceRecord { workspaceId: string; createdAt: number; }
interface VersionRecord { label: string; incident: IncidentRecord & { id: string }; createdAt: number; createdBy: string; createdByName: string; }
interface RouteMasterPair { systemKey: string; routeSegment: string; }
interface RouteMasterChunkRecord { batchId: string; chunkIndex: number; items: RouteMasterPair[]; createdAt: number; createdBy: string; }
interface RouteMasterMetaRecord { currentBatchId: string; count: number; fileName: string; sheetName: string; systemKeyColumn: string; routeSegmentColumn: string; updatedAt: number; updatedBy: string; updatedByName: string; }

const defaults: SettingsRecord = { groups: ['FLP_3rd_MANDAU', 'FLP_3rd_KARAWANG', 'FLP_3rd_JABODETABEK'], picAreas: ['Karawang Barat', 'Mandau', 'Jabodetabek'], picNames: ['Dede Sopian'], rootCauses: ['Impact Hit by Truck', 'FO Cut', 'Hardbending', 'Power Issue', 'Under Investigation'], actions: ['Splicing & Jumper', 'Splicing Permanent', 'Replace Patchcord', 'Re-route Traffic', 'Monitoring'], progressPhrases: ['We Already Open TT', 'Team Confirm prepare Tools', 'Team OTW lokasi', 'Team tiba di lokasi', 'Team proses pengecekan', 'Team proses pencarian physical CP', 'Team proses kupas kabel kedua sisi', 'Team proses setting JC', 'Team progress penyambungan', 'Confirm link normal TT closed'], sites: ['KARAWANG_CITY', 'KIIC', 'KARABAINDAH'], slaCriticalMinutes: 15, slaMajorMinutes: 30, slaMinorMinutes: 60, staleUpdateMinutes: 45, updatedAt: Date.now() };
const profileTable = (userId: string) => `profiles:${userId}`;
const memberTable = (workspaceId: string) => `members:${workspaceId}`;
const incidentTable = (workspaceId: string) => `incidents:${workspaceId}`;
const settingsTable = (workspaceId: string) => `settings:${workspaceId}`;
const versionTable = (workspaceId: string, incidentId: string) => `versions:${workspaceId}:${incidentId}`;
const routeMasterTable = (workspaceId: string) => `route-master:${workspaceId}`;
const routeMasterMetaTable = (workspaceId: string) => `route-master-meta:${workspaceId}`;
const auditTable = (workspaceId: string, incidentId: string) => `audit:${workspaceId}:${incidentId}`;
const incidentKeyTable = (workspaceId: string, normalizedKey: string) => `incident-key:${workspaceId}:${incidentKeyHash(normalizedKey)}`;
const SLA_WORKSPACE_TABLE = 'sla-workspaces';
const text = (value: unknown, fallback = '') => typeof value === 'string' ? value.slice(0, 5000) : fallback;
const imageBase64 = (value: unknown) => { if (typeof value !== 'string') return ''; const cleaned = value.replace(/^data:[^;]+;base64,/, '').replace(/\s+/g, ''); return cleaned.length > 0 && cleaned.length <= 8000000 ? cleaned : ''; };
const nowId = () => `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 9)}`;
const pick = <T extends string>(value: unknown, choices: readonly T[], fallback: T): T => choices.includes(value as T) ? value as T : fallback;
const normalizeCondition = (value: unknown): IncidentCondition => { const normalized = text(value).trim().toUpperCase().replace(/\s+/g, ' '); return normalized === 'DEGRADED' || normalized === 'UP - DEGRADED' ? 'UP - Degraded' : 'DOWN'; };
const canReview = (role: Role) => role === 'admin' || role === 'supervisor';
const geoNumber = (value: unknown) => { if (typeof value === 'number') return Number.isFinite(value) ? value : null; const parsed = Number(text(value).trim().replace(',', '.')); return Number.isFinite(parsed) ? parsed : null; };
const truncateGeo6 = (value: number) => Math.trunc(value * 1000000) / 1000000;
const formatGeo = (latitude: number, longitude: number) => `${truncateGeo6(latitude).toFixed(6)}, ${truncateGeo6(longitude).toFixed(6)}`;
type ParsedGeoText = { latitude: number; longitude: number; rawCoordinate: string; confidence: 'high' | 'medium' };
const parseAngleFragment = (fragment: string, axis: 'lat' | 'lon') => { const normalized = fragment.replace(/[−–—]/g, '-'); const hemisphere = normalized.match(/[NSEW]/i)?.[0]?.toUpperCase(); const nums = Array.from(normalized.matchAll(/[+-]?\d{1,3}(?:[.,]\d+)?/g)).slice(0, 3).map(match => Number(match[0].replace(',', '.'))); if (!nums.length || nums.some(value => !Number.isFinite(value))) return null; const hasDmsMarks = /[°º˚'′’"″”]/.test(normalized); let value = hasDmsMarks && nums.length > 1 ? Math.abs(nums[0]) + Math.abs(nums[1]) / 60 + (nums[2] == null ? 0 : Math.abs(nums[2]) / 3600) : Math.abs(nums[0]); const negative = hemisphere === 'S' || hemisphere === 'W' || (!hemisphere && nums[0] < 0); if (negative) value = -value; const max = axis === 'lat' ? 90 : 180; return Math.abs(value) <= max ? value : null; };
const parseGeoOcrText = (source: string): ParsedGeoText | null => { const value = source.replace(/\u00a0/g, ' ').replace(/[\u200b-\u200d\ufeff]/g, '').replace(/[−–—]/g, '-'); const hemiRegex = /([+-]?\d{1,3}(?:[.,]\d+)?)\s*(?:[°º˚]\s*(\d{1,2}(?:[.,]\d+)?)\s*(?:['′’]\s*(\d{1,2}(?:[.,]\d+)?)\s*(?:["″”])?)?)?\s*([NSEW])/gi; const lat: Array<{ value: number; raw: string; index: number }> = []; const lon: Array<{ value: number; raw: string; index: number }> = []; for (const match of value.matchAll(hemiRegex)) { const hem = match[4].toUpperCase(); const axis = hem === 'N' || hem === 'S' ? 'lat' : 'lon'; const parsed = parseAngleFragment(match[0], axis); if (parsed == null) continue; (axis === 'lat' ? lat : lon).push({ value: parsed, raw: match[0].trim(), index: match.index || 0 }); } if (lat.length && lon.length) { let best: { latitude: typeof lat[number]; longitude: typeof lon[number]; distance: number } | null = null; for (const latitude of lat) for (const longitude of lon) { const distance = Math.abs(latitude.index - longitude.index); if (!best || distance < best.distance) best = { latitude, longitude, distance }; } if (best) return { latitude: best.latitude.value, longitude: best.longitude.value, rawCoordinate: `${best.latitude.raw} ${best.longitude.raw}`.slice(0, 240), confidence: 'high' }; } const findLabel = (pattern: RegExp, axis: 'lat' | 'lon') => { const match = pattern.exec(value); if (!match) return null; const fragment = value.slice(match.index + match[0].length, match.index + match[0].length + 72).split(/\n|\r|\|/)[0]; const parsed = parseAngleFragment(fragment, axis); return parsed == null ? null : { value: parsed, raw: fragment.trim() }; }; const labeledLat = findLabel(/\b(?:lat|latitude)\b\s*[:=]?\s*/i, 'lat'); const labeledLon = findLabel(/\b(?:lon|lng|long|longitude)\b\s*[:=]?\s*/i, 'lon'); if (labeledLat && labeledLon) return { latitude: labeledLat.value, longitude: labeledLon.value, rawCoordinate: `${labeledLat.raw} ${labeledLon.raw}`.slice(0, 240), confidence: 'high' }; const decimals = Array.from(value.matchAll(/[+-]?\d{1,3}(?:[.,]\d{3,})/g)).map(match => ({ raw: match[0], index: match.index || 0, value: Number(match[0].replace(',', '.')) })).filter(item => Number.isFinite(item.value)); let bestDecimal: { latitude: typeof decimals[number]; longitude: typeof decimals[number]; distance: number } | null = null; for (let i = 0; i < decimals.length; i += 1) { const latitude = decimals[i]; if (Math.abs(latitude.value) > 90) continue; for (let j = i + 1; j < Math.min(decimals.length, i + 4); j += 1) { const longitude = decimals[j]; if (Math.abs(longitude.value) > 180) continue; const distance = longitude.index - latitude.index; if (distance < 1 || distance > 180) continue; if (!bestDecimal || distance < bestDecimal.distance) bestDecimal = { latitude, longitude, distance }; } } if (bestDecimal) return { latitude: bestDecimal.latitude.value, longitude: bestDecimal.longitude.value, rawCoordinate: `${bestDecimal.latitude.raw}, ${bestDecimal.longitude.raw}`.slice(0, 240), confidence: 'medium' }; const pairRegex = /([+-]?\d{1,2}(?:[.,]\d{2,}))\s*([NS])?\s*(?:[,;|/]\s*|\s+)\s*([+-]?\d{2,3}(?:[.,]\d{2,}))\s*([EW])?/gi; for (const match of value.matchAll(pairRegex)) { let latitude = Number(match[1].replace(',', '.')); let longitude = Number(match[3].replace(',', '.')); if (match[2]?.toUpperCase() === 'S') latitude = -Math.abs(latitude); if (match[2]?.toUpperCase() === 'N') latitude = Math.abs(latitude); if (match[4]?.toUpperCase() === 'W') longitude = -Math.abs(longitude); if (match[4]?.toUpperCase() === 'E') longitude = Math.abs(longitude); if (Number.isFinite(latitude) && Number.isFinite(longitude) && Math.abs(latitude) <= 90 && Math.abs(longitude) <= 180) return { latitude, longitude, rawCoordinate: match[0].trim().slice(0, 240), confidence: match[2] && match[4] ? 'high' : 'medium' }; } return null; };
type GeoOcrDiagnostic = { view: number; mode: 'GEMINI'; text: string; coordinate: string; confidence: '' | 'high' | 'medium' };
const sanitizeGeoCoordinate = (raw: unknown, actorId: string, index = 0): GeoCoordinateRecord | null => { const item = raw && typeof raw === 'object' ? raw as Record<string, unknown> : {}; const latitude = geoNumber(item.latitude); const longitude = geoNumber(item.longitude); if (latitude == null || longitude == null || Math.abs(latitude) > 90 || Math.abs(longitude) > 180) return null; return { id: text(item.id, `geo-${index}-${nowId()}`), latitude, longitude, normalized: formatGeo(latitude, longitude), sourceName: text(item.sourceName, 'GeoTag photo').slice(0, 160), rawCoordinate: text(item.rawCoordinate).slice(0, 240), extractedAt: typeof item.extractedAt === 'number' ? item.extractedAt : Date.now(), extractedBy: text(item.extractedBy, actorId), confidence: item.confidence === 'medium' ? 'medium' : 'high', verified: typeof item.verified === 'boolean' ? item.verified : true, verifiedAt: typeof item.verifiedAt === 'number' ? item.verifiedAt : 0, verifiedBy: text(item.verifiedBy) }; };
const sanitizeGeoCoordinates = (value: unknown, current: GeoCoordinateRecord[] | undefined, actorId: string) => { const source = Array.isArray(value) ? value : current || []; return source.slice(0, 20).reduce<GeoCoordinateRecord[]>((list, raw, index) => { const coordinate = sanitizeGeoCoordinate(raw, actorId, index); if (coordinate) list.push(coordinate); return list; }, []); };
const sanitizeCutPoints = (value: unknown, current: CutPointRecord[] | undefined, legacyCoordinates: unknown, actorId: string): CutPointRecord[] => { let source: unknown[] = []; if (Array.isArray(value)) source = value; else if (Array.isArray(current)) source = current; else if (Array.isArray(legacyCoordinates)) source = legacyCoordinates.map((coordinate, index) => ({ id: `legacy-cp-${index + 1}`, label: `CP ${index + 1}`, coordinate })); return source.slice(0, 20).map((raw, index) => { const item = raw && typeof raw === 'object' ? raw as Record<string, unknown> : {}; const label = text(item.label).trim().slice(0, 120) || `CP ${index + 1}`; return { id: text(item.id, `cp-${index}-${nowId()}`), label, coordinate: sanitizeGeoCoordinate(item.coordinate, actorId, index) }; }); };
const flattenCutPointCoordinates = (cutPoints: CutPointRecord[]) => cutPoints.flatMap(item => item.coordinate ? [item.coordinate] : []);
const hydrateIncident = (incident: IncidentRecord & { id?: string }) => { const cutPoints = sanitizeCutPoints(incident.cutPoints, incident.cutPoints, incident.geoCoordinates, incident.updatedBy || incident.createdBy || ''); return { ...incident, condition: normalizeCondition(incident.condition), cutPoints, geoCoordinates: flattenCutPointCoordinates(cutPoints), parentIncidentId: incident.parentIncidentId || '', closingEvidenceNote: incident.closingEvidenceNote || '', assignedToUserId: incident.assignedToUserId || '', assignedToName: incident.assignedToName || '', acknowledgedAt: incident.acknowledgedAt || 0, acknowledgedBy: incident.acknowledgedBy || '', handoverNote: incident.handoverNote || '', handoverAt: incident.handoverAt || 0, handoverBy: incident.handoverBy || '', reopenReason: incident.reopenReason || '', resolvedAt: incident.resolvedAt || 0, resolvedBy: incident.resolvedBy || '', deletedAt: incident.deletedAt || 0, deletedBy: incident.deletedBy || '', deleteReason: incident.deleteReason || '' }; };

async function getProfile(userId: string) { const { items } = await db.list<ProfileRecord>(profileTable(userId), { limit: 1 }); return items[0] || null; }
async function listMembers(workspaceId: string) { const { items } = await db.list<MemberRecord>(memberTable(workspaceId), { limit: 100 }); return items.sort((a, b) => a.joinedAt - b.joinedAt); }
async function getSettings(workspaceId: string) { const { items } = await db.list<SettingsRecord>(settingsTable(workspaceId), { limit: 1 }); if (items[0]) return { ...defaults, ...items[0], slaCriticalMinutes: items[0].slaCriticalMinutes || defaults.slaCriticalMinutes, slaMajorMinutes: items[0].slaMajorMinutes || defaults.slaMajorMinutes, slaMinorMinutes: items[0].slaMinorMinutes || defaults.slaMinorMinutes, staleUpdateMinutes: items[0].staleUpdateMinutes || defaults.staleUpdateMinutes }; const [id] = await db.add(settingsTable(workspaceId), [{ ...defaults, updatedAt: Date.now() }]); return { ...defaults, id: id || undefined }; }
async function ensureSlaWorkspace(workspaceId: string) { const { items } = await db.list<SlaWorkspaceRecord>(SLA_WORKSPACE_TABLE, { limit: 500 }); if (!items.some(item => item.workspaceId === workspaceId)) await db.add(SLA_WORKSPACE_TABLE, [{ workspaceId, createdAt: Date.now() }]); }
async function getRouteMasterMeta(workspaceId: string) { const { items } = await db.list<RouteMasterMetaRecord>(routeMasterMetaTable(workspaceId), { limit: 1 }); return items[0] || null; }
async function ensureProfile(user: { userId: string; email?: string; name?: string }) { const existing = await getProfile(user.userId); if (existing) { await ensureSlaWorkspace(existing.workspaceId); return existing; } const createdAt = Date.now(); const workspaceId = user.userId; const profile: ProfileRecord = { userId: user.userId, workspaceId, role: 'admin', email: user.email || '', name: user.name || 'Admin NOC', createdAt }; const [profileId] = await db.add(profileTable(user.userId), [{ ...profile }]); if (!profileId) throw new Error('Failed to create profile'); await db.add(memberTable(workspaceId), [{ ...profile, joinedAt: createdAt }]); await db.add(settingsTable(workspaceId), [{ ...defaults, updatedAt: createdAt }]); await ensureSlaWorkspace(workspaceId); return { ...profile, id: profileId }; }
const cleanList = (value: unknown, fallback: string[]) => Array.isArray(value) ? value.filter(item => typeof item === 'string').map(item => String(item).trim()).filter(Boolean).slice(0, 250) : fallback;
const positiveMinutes = (value: unknown, fallback: number) => typeof value === 'number' && Number.isFinite(value) ? Math.max(5, Math.min(1440, Math.round(value))) : fallback;
function normalizeSettings(body: Record<string, unknown>, current?: SettingsRecord): SettingsRecord { const source = current || defaults; return { groups: cleanList(body.groups, source.groups), picAreas: cleanList(body.picAreas, source.picAreas), picNames: cleanList(body.picNames, source.picNames), rootCauses: cleanList(body.rootCauses, source.rootCauses), actions: cleanList(body.actions, source.actions), progressPhrases: cleanList(body.progressPhrases, source.progressPhrases), sites: cleanList(body.sites, source.sites), slaCriticalMinutes: positiveMinutes(body.slaCriticalMinutes, source.slaCriticalMinutes || defaults.slaCriticalMinutes), slaMajorMinutes: positiveMinutes(body.slaMajorMinutes, source.slaMajorMinutes || defaults.slaMajorMinutes), slaMinorMinutes: positiveMinutes(body.slaMinorMinutes, source.slaMinorMinutes || defaults.slaMinorMinutes), staleUpdateMinutes: positiveMinutes(body.staleUpdateMinutes, source.staleUpdateMinutes || defaults.staleUpdateMinutes), updatedAt: Date.now() }; }
