async function saveSnapshot(workspaceId: string, incidentId: string, incident: IncidentRecord, actor: { userId: string; name?: string }, label: string) { await db.add(versionTable(workspaceId, incidentId), [{ label, incident: { ...incident, id: incidentId }, createdAt: Date.now(), createdBy: actor.userId, createdByName: actor.name || '' }]); }
async function notifyIncident(workspaceId: string, kind: string, incident?: IncidentRecord & { id: string }, id?: string) { await notifySubscribers('workspace', workspaceId, { kind, incident, id }); }
async function appendAudit(workspaceId: string, incidentId: string, action: string, summary: string, actor: { userId: string; name?: string; email?: string }, before?: IncidentRecord, after?: IncidentRecord) { const entry: AuditRecord = { action, summary: summary.slice(0, 500), changedFields: changedFieldNames(before, after), fromRevision: before?.revision || 0, toRevision: after?.revision || before?.revision || 0, actorId: actor.userId, actorName: actor.name || actor.email || 'NOC User', createdAt: Date.now() }; await db.add(auditTable(workspaceId, incidentId), [entry]); }
