export async function slaReminderHandler() {
  const workspacePage = await db.list<SlaWorkspaceRecord>(SLA_WORKSPACE_TABLE, { limit: 500 });
  const workspaceIds = Array.from(new Set(workspacePage.items.map(item => item.workspaceId).filter(Boolean)));
  let alerts = 0;
  let scanned = 0;
  for (const workspaceId of workspaceIds) {
    try {
      const result = await processOperationsEscalations(workspaceId);
      alerts += result.alerts;
      scanned += result.scanned;
    } catch (err) {
      const failure = err as { statusCode?: number; code?: string };
      if (failure.statusCode === 429 || failure.code === 'AppDatabaseQuotaExceeded') throw err;
      console.warn('ops_escalation_workspace_failed', workspaceId, err instanceof Error ? err.message : 'unknown');
    }
  }
  return { statusCode: 200, body: JSON.stringify({ workspaces: workspaceIds.length, scanned, alerts, reminders: alerts }) };
}
